     if (!query.exec(QStringLiteral(
             "SELECT id, map_id, status, date, tag, color, notes, created_at, updated_at"
             " FROM records WHERE status = 'draft' LIMIT 1"))) {
         failQuery(query, error, QStringLiteral("Could not load the draft"));
