const QString destination = QDir(folder).filePath(QStringLiteral("poisonlog.db"));
QFile::remove(destination);
QString error;
if (!m_database->backupTo(destination, &error)) {
    setError(error);
    return;
}

const QFileInfo image(resolveMapImagePath(m_map.imagePath));
const QString relative = relativeImagePath(image.absoluteFilePath());
QString imageDestination;
if (QDir::isRelativePath(relative)) {
    // The image already uses the portable layout: mirror it 1:1.
    imageDestination = QDir(folder).filePath(relative);
} else {
    // Custom image outside the data folder: copy it into the standard
    // maps/ layout and point the backed-up database row at it.
    imageDestination = QDir(QDir(folder).filePath(QStringLiteral("maps")))
        .filePath(image.fileName());
}
if (!QDir().mkpath(QFileInfo(imageDestination).absolutePath())) {
    setError(QStringLiteral("The backup map directory could not be created: %1")
        .arg(QFileInfo(imageDestination).absolutePath()));
    return;
}
QFile::remove(imageDestination);
if (!QFile::copy(image.absoluteFilePath(), imageDestination)) {
    setError(QStringLiteral("The map image could not be backed up to: %1")
        .arg(imageDestination));
    return;
}

if (QDir::isAbsolutePath(imageDestination) && QDir(folder).isSameFile(folder)) {
    // Keep the backed-up database self-consistent for restored images.
    const QString backupRelative = relativeImagePath(imageDestination);
    if (QDir::isRelativePath(backupRelative)) {
        Database backupDatabase(destination);
        if (backupDatabase.open(&error))
            backupDatabase.saveMapImagePath(backupRelative, &error);
        if (!error.isEmpty())
            setError(error);
    }
}

setStatus(QStringLiteral("Backup created in %1.").arg(folder));

